{"plan_objective_id": 1, "updated_plan_objective_json": "{
  "id": 1,
  "objective": "Search for literature on combined ATR-FTIR + conductivity flow cells for electrolyte speciation",
  "rationale": "Found Kachko et al. on NIR+conductivity+other physical properties for CO2 capture; Bryan et al. on Raman+conductivity+density for nuclear reprocessing. Need to look for more direct ATR-FTIR + conductivity combination.",
  "status": "completed",
  "result": "Found Kachko 2015 (pilot plant PLS with conductivity+NIR+density), Bryan 2013 (Raman+conductivity+density for nuclear), and Maggioni 2019 (Raman+ATR-FTIR for salt solutions). No single paper found combining ONLY ATR-FTIR + conductivity in one flow cell, but multi-sensor fusion combining spectroscopy with conductivity is well documented.",
  "evaluation": "Sufficient coverage of sensor fusion approaches combining spectroscopy with conductivity"
}"}

{"plan_objective_id": 2, "updated_plan_objective_json": "{
  "id": 2,
  "objective": "Search for literature on chemometrics vs neural network models for concentrated multicomponent electrolyte spectral analysis",
  "rationale": "Part (b) focuses on modeling approaches for nonlinear spectral mixing",
  "status": "completed",
  "result": "Found Angulo 2022 (ML vs LR for FTIR mixtures), Zavala-Ortiz 2022 (PLS vs ANN vs SVR for NIR), Blanco 2000 (PLS vs ANN for nonlinear NIR), Maggioni 2019 (MCR-ALS BSS for Raman/ATR-FTIR salt solutions), Carrillo-Bohorquez 2024 (challenges of HCE characterization). Coverage of PLS, MCR-ALS, CLS, and neural network approaches is adequate.",
  "evaluation": "Good coverage of chemometric and ML model comparison"
}"}

{"plan_objective_id": 3, "updated_plan_objective_json": "{
  "id": 3,
  "objective": "Search for literature on in-line Raman and IR spectroscopy coupled to flow systems and robotic liquid handling",
  "rationale": "Part (d) asks about practical considerations for fiber-coupled Raman vs IR integration into robots",
  "status": "completed",
  "result": "Found Nelson 2021 (combined Raman+UV-Vis microfluidic monitoring), Bryan 2013 (fiber-coupled Raman/Vis-NIR for nuclear), Jurina 2023 (spectroscopy in microreactors), Seifrid 2022 (self-driving labs with inline UV-Vis/PL), Klaverdijk 2025 (Raman bioreactor monitoring). Good coverage of Raman advantages (low water interference, fiber compatibility) vs IR challenges (water absorption, ATR requirement).",
  "evaluation": "Comprehensive coverage of Raman vs IR for fiber-coupled flow/robotic integration"
}"}

{"plan_objective_id": 4, "updated_plan_objective_json": "{
  "id": 4,
  "objective": "Training data requirements and validation strategies",
  "rationale": "Part (c) asks specifically about training data size and held-out/blind test validation",
  "status": "completed",
  "result": "Found: Angulo 2022 (40 spectra sufficient for ternary LR, ANN needs more; 80/20 split); Zavala-Ortiz 2022 (168 spectra, 135 cal/33 val, Kennard-Stone split); Kachko 2015 (53 compositions, 5-level fractional factorial); Maggioni 2019 (17 samples for BSS). Multiple validation approaches documented.",
  "evaluation": "Good quantitative detail on training data requirements and validation approaches"
}"}

{"plan_objective_id": 5, "updated_plan_objective_json": "{
  "id": 5,
  "objective": "Gather detailed evidence from retrieved papers on all four sub-questions",
  "rationale": "Evidence already gathered through multiple rounds of gather_evidence calls",
  "status": "completed",
  "result": "41 evidence items gathered from 14+ relevant papers",
  "evaluation": "Sufficient evidence base for comprehensive answer"
}"}

{"plan_objective_id": 6, "updated_plan_objective_json": "{
  "id": 6,
  "objective": "Search for sensor fusion approaches combining vibrational spectroscopy with conductivity or other physical measurements",
  "rationale": "Already covered through Bryan 2013, Kachko 2015/2016 evidence",
  "status": "completed",
  "result": "Covered by Bryan 2013 (Raman + conductivity + Coriolis density), Kachko 2015 (NIR + conductivity + density + pH + refractive index + sound velocity), and Maggioni 2019 (simultaneous Raman + ATR-FTIR).",
  "evaluation": "Adequate sensor fusion evidence"
}"}

{"plan_objective_id": 7, "updated_plan_objective_json": "{
  "id": 7,
  "objective": "Create artifacts and submit final answer covering all four parts with specific paper citations",
  "rationale": "Synthesize all gathered evidence into a coherent, well-cited technical answer",
  "status": "in-progress",
  "result": null,
  "evaluation": null
}"}

